excels.excel:

EXPORT WITH SHEET="固定资产盘点表", HEADER=true,
    MAPPING={"a":"使用部门","b":"资产编号","c":"资产名称","d":"账面数量","e":"实盘数量","f":"盘盈盘亏","g":"资产原值"},
    FORMAT={"d":"#,##0","e":"#,##0","f":"#,##0","g":"#,##0.00"},
    FORMULAS={
        F2:'E2-D2',F3:'E3-D3',F4:'E4-D4',
        D5:'SUM(D2:D4)',E5:'SUM(E2:E4)',F5:'E5-D5',G5:'SUM(G2:G4)',
        F6:'E6-D6',F7:'E7-D7',
        D8:'SUM(D6:D7)',E8:'SUM(E6:E7)',F8:'E8-D8',G8:'SUM(G6:G7)',
        D9:'D5+D8',E9:'E5+E8',F9:'E9-D9',G9:'G5+G8'
    },
    STYLE={
        ROW 5:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 9:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F3:{color:red,bold:true}
    },
    MERGE:{
        RANGE A2:A4 WITH MERGE_WITH_FIRST,
        RANGE A6:A7 WITH MERGE_WITH_FIRST
    }
